import { adminCreateSchema, adminUpdateSchema, loginSchema, updateSchema, usernameSchema } from '../config/contentSchema.js';
import { sessionCookie } from '../middleware/adminAuth.js';

/** Validates login input and returns only non-secret session metadata. */
export async function login(request, response) {
  const parsed = loginSchema.safeParse(request.body);
  if (!parsed.success) return response.status(400).json({ error: { code: 'INVALID_INPUT', message: 'Enter a valid username and password.' } });
  const session = await request.app.locals.adminStore?.login(parsed.data.username, parsed.data.password);
  if (!session) return response.status(401).json({ error: { code: 'INVALID_LOGIN', message: 'Username or password is incorrect.' } });
  response.set('Set-Cookie', sessionCookie(session.token, session.expiresAt));
  response.json({ username: session.username, csrfToken: session.csrfToken, expiresAt: session.expiresAt });
}

/** Allows page reloads to restore session state without browser token storage. */
export function getSession(request, response) { response.json(request.adminSession); }

/** Revokes the database session and removes its cookie. */
export async function logout(request, response) {
  await request.app.locals.adminStore.logout(request.adminToken);
  response.set('Set-Cookie', sessionCookie('', 0)).status(204).end();
}

const invalidAdmin = { error: { code: 'INVALID_INPUT', message: 'Usernames use 3-64 letters, numbers, dots, underscores, or hyphens. Passwords need 12-256 characters.' } };

/** Sends store errors that carry a status as JSON; unexpected errors fall through to the handler. */
async function respondWithStoreErrors(response, action) {
  try { await action(); }
  catch (error) {
    if (error.status && error.code) return response.status(error.status).json({ error: { code: error.code, message: error.message } });
    throw error;
  }
}

/** Lists administrator usernames and marks the signed-in account. */
export function listAdmins(request, response) {
  response.json({ admins: request.app.locals.adminStore.list(), current: request.adminSession.username });
}

/** Creates an administrator with a validated username and password. */
export async function createAdmin(request, response) {
  const parsed = adminCreateSchema.safeParse(request.body);
  if (!parsed.success) return response.status(400).json(invalidAdmin);
  await respondWithStoreErrors(response, async () => {
    await request.app.locals.adminStore.create(parsed.data.username, parsed.data.password);
    response.status(201).json({ username: parsed.data.username });
  });
}

/** Renames or re-passwords an administrator, keeping the editor's own session alive. */
export async function updateAdmin(request, response) {
  const parsed = adminUpdateSchema.safeParse(request.body);
  if (!parsed.success || !usernameSchema.safeParse(request.params.username).success) return response.status(400).json(invalidAdmin);
  await respondWithStoreErrors(response, async () => {
    await request.app.locals.adminStore.update(request.params.username, parsed.data, request.adminToken);
    const username = parsed.data.username || request.params.username;
    response.json({ username, current: request.params.username === request.adminSession.username ? username : request.adminSession.username });
  });
}

/** Deletes another administrator; signed-in accounts cannot delete themselves. */
export async function deleteAdmin(request, response) {
  if (request.params.username === request.adminSession.username) return response.status(400).json({ error: { code: 'SELF_DELETE', message: 'You cannot delete the account you are signed in with.' } });
  await respondWithStoreErrors(response, () => {
    request.app.locals.adminStore.remove(request.params.username);
    response.status(204).end();
  });
}

/** Loads the current document plus a version required for safe publishing. */
export async function getEditableContent(request, response) { response.json(await request.app.locals.contentStore.readWithVersion()); }

/** Validates the complete CMS contract and atomically publishes a versioned document. */
export async function updateContent(request, response) {
  const parsed = updateSchema.safeParse(request.body);
  if (!parsed.success) return response.status(400).json({ error: { code: 'INVALID_CONTENT', message: 'Content is invalid. Check links, numeric ranges, and required fields.', fields: parsed.error.issues.map(issue => issue.path.join('.')).slice(0, 20) } });
  if (!request.app.locals.mediaStore.validReferences(parsed.data.content)) return response.status(400).json({ error: { code: 'INVALID_MEDIA', message: 'An image is missing. Upload it again before publishing.' } });
  try { response.json(await request.app.locals.contentStore.save(parsed.data.content, parsed.data.version)); }
  catch (error) {
    if (error.status === 409) return response.status(409).json({ error: { code: 'CONFLICT', message: 'Another edit was published. Reload content before saving.' } });
    throw error;
  }
}